"""Dashboard demo pass, Part 2: data/demo_full.csv (generated by
scripts/generate_demo_full.py) is the one fixture in this suite with a real
trend AND a real correlation, both strong enough to clear
app/exploration/config.py's floors at once - every other fixture in this
test suite was deliberately built to avoid tripping them (or to trip one in
isolation). LINE (trend) and SCATTER (correlation) charts may never have
been exercised end-to-end before this - this is that test, run once against
the real exploration -> narrative -> chart pipeline, no mocked findings.
"""

from __future__ import annotations

from pathlib import Path

from tests.golden_scenarios import ingest_and_wait
from tests.test_modeling_pipeline import predict_and_wait

DEMO_FULL_CSV = Path(__file__).resolve().parent.parent / "data" / "demo_full.csv"


def test_demo_full_dataset_exercises_every_deterministic_chart_type(client):
    assert DEMO_FULL_CSV.exists(), "run `python scripts/generate_demo_full.py` from backend/ first"
    source_id = client.post("/sources", json={"type": "file", "connection_config": {"path": str(DEMO_FULL_CSV)}}).json()["id"]
    result = ingest_and_wait(client, source_id)
    assert result["status"] == "completed"
    run_id = result["run_id"]

    findings = client.get(f"/findings/{run_id}").json()["findings"]["findings"]
    finding_types = {f["finding_type"] for f in findings}
    assert "trend" in finding_types, "expected a trend finding for revenue/order_date"
    assert "correlation" in finding_types, "expected a correlation finding for revenue/cost"

    report = client.get(f"/reports/{run_id}").json()
    chart_types = {c["chart_type"] for c in report["chart_refs"]}
    # All four deterministic chart types (app/narrative/charts.py), from one
    # dataset: a genuine trend -> line, a genuine correlation -> scatter, a
    # discrete 1-5 rating -> bar (value counts), and a plain continuous
    # numeric column -> histogram.
    assert "line" in chart_types, f"trend finding exists but no line chart was produced - chart_types={chart_types}"
    assert "scatter" in chart_types, f"correlation finding exists but no scatter chart was produced - chart_types={chart_types}"
    assert "bar" in chart_types
    assert "histogram" in chart_types

    # Each chart must actually carry real per-row data, not a placeholder -
    # Plotly encodes a numeric trace as {"dtype": "f8", "bdata": <base64>}
    # rather than a plain JSON array (a real, standard, plotly.js-decodable
    # format - not a truncated payload), so this decodes it rather than
    # naively taking len() of the dict.
    import base64
    import struct

    def _decode_axis(value) -> int:
        if isinstance(value, dict) and "bdata" in value:
            raw = base64.b64decode(value["bdata"])
            return len(raw) // struct.calcsize("d")
        return len(value)

    line_chart = next(c for c in report["chart_refs"] if c["chart_type"] == "line")
    scatter_chart = next(c for c in report["chart_refs"] if c["chart_type"] == "scatter")
    assert _decode_axis(line_chart["figure_json"]["data"][0]["x"]) > 900  # ~913 distinct days
    assert _decode_axis(line_chart["figure_json"]["data"][0]["y"]) > 900
    assert _decode_axis(scatter_chart["figure_json"]["data"][0]["x"]) > 1000  # thousands of per-order rows
    assert _decode_axis(scatter_chart["figure_json"]["data"][0]["y"]) > 1000


def test_demo_full_dataset_forecast_beats_naive_baseline(client):
    """Part 2's other acceptance criterion: a forecast on the trending
    column (revenue, summed monthly) must beat the naive-last-value
    baseline, exercising the exact real Prophet/ARIMA fit the Predict page
    demo needs to succeed - no constructed TrainingOutcome shortcut here."""
    assert DEMO_FULL_CSV.exists()
    source_id = client.post("/sources", json={"type": "file", "connection_config": {"path": str(DEMO_FULL_CSV)}}).json()["id"]
    result = ingest_and_wait(client, source_id)
    run_id = result["run_id"]

    body = predict_and_wait(client, {"run_id": run_id, "target_column": "revenue"})
    assert body["task_type"] == "forecast"
    assert body["status"] == "answered", (body["escalation_reason"], body["escalation_detail"])
    naive = next(b for b in body["baseline_scores"] if b["model_family"] == "naive")
    assert body["out_of_sample_score"] < naive["out_of_sample_score"]
    assert body["forecast_series"] is not None
    assert len(body["forecast_series"]["historical"]) >= 24
    assert len(body["forecast_series"]["forecast"]) > 0
